import{z as E,x as p,o as r,c as A,q as i,j as t,D as a,d as s,s as o,S as d,b as l}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"NVMe 队列与驱动","description":"","frontmatter":{"title":"NVMe 队列与驱动","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/nvme-driver.md","filePath":"cs/nvme-driver.md","lastUpdated":1791413859000}'),B={name:"cs/nvme-driver.md"};function m(S,e,c,C,h,u){const n=p("Mermaid");return r(),A("div",null,[e[2]||(e[2]=i('<h1 id="nvme-队列与驱动" tabindex="-1">NVMe 队列与驱动 <a class="header-anchor" href="#nvme-队列与驱动" aria-label="Permalink to &quot;NVMe 队列与驱动&quot;">​</a></h1><div class="epigraph"><p>NVMe 给每个核一对提交队列与完成队列：驱动把命令写进 SQ，门铃通知控制器，CQ 与 MSI-X 带回完成。</p><footer>—— 据 NVM Express 基规范；Linux nvme 驱动文档</footer></div><p><a href="/cs/blk-schedulers">上一课</a>可以把请求直通硬件队列。SCSI 时代一条深队列加锁；NVMe 把并行做成协议。缺口是 <strong>NVMe 驱动</strong>：队列对、门铃、PRP/SGL、与 blk-mq 的映射——不是闪存转换层内部。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一次全局请求锁在百万 IOPS 上会死。NVMe：最多成千上万对队列，驱动按 CPU 或 blk-mq hctx 绑一对 SQ/CQ。提交：填 64 字节命令（读写、flush、admin），写门铃寄存器。完成：轮询或中断读 CQ，更新 blk 请求。缺口：admin 队列与 I/O 队列分离；命名空间当块设备；热插与重置。本课不把 NVMe-oF 的 RDMA 写完。</p><p><span class="marginnote">PRP 是页列表；SGL 更一般。写屏障后课才讲 FUA/NVMe flush。本课对象是队列与命令环。</span></p><p><span class="marginnote">数字实例：每条 NVMe 命令固定 64 字节，队列以环状复用内存。一对深度 1024 的 SQ/CQ，SQ 环本身只占 1024 × 64 字节 = 64 KB（CQ 条目 16 字节，更小），成千上万对也不到百 MB 量级，这是「每核一对」在内存上可承受的原因。</span></p><p><span class="marginnote">术语翻译：PRP 就是把要传输的数据用一串 4 KB 物理页地址串起来的「页清单」，控制器按地址直接 DMA；SGL 是更一般的散布-聚集版本，允许每段长度各不相同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>探测：PCI BAR、能力、创建 CQ/SQ。I/O：<code>nvme_queue_rq</code> 把 bio 译成命令，DMA 映射用户或页缓存页。完成路径：<code>nvme_irq</code> 或 poll 消费 CQ，<code>blk_mq_complete_request</code>。对照 SCSI：没有 SCSI 命令封装的 ATA 翻译层，少一次协议。对照 <a href="/cs/device-nodes">设备节点</a>：<code>/dev/nvme0n1</code> 仍是块 inode。</p>',10)),(r(),t(d,null,{default:a(()=>[o(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20RQ%5B%22blk-mq%20%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20SQ%5B%22%E6%8F%90%E4%BA%A4%E9%98%9F%E5%88%97%22%5D%0A%20%20SQ%20--%3E%20DB%5B%22%E9%97%A8%E9%93%83%22%5D%0A%20%20DB%20--%3E%20CTL%5B%22%E6%8E%A7%E5%88%B6%E5%99%A8%22%5D%0A%20%20CTL%20--%3E%20CQ%5B%22%E5%AE%8C%E6%88%90%E9%98%9F%E5%88%97%22%5D%0A%20%20CQ%20--%3E%20IRQ%5B%22%E4%B8%AD%E6%96%AD%E6%88%96%E8%BD%AE%E8%AF%A2%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=l("h2",{id:"机制",tabindex:"-1"},[s("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=l("p",null,"NVMe 把块设备从「一条 SCSI 管道」换成「每核私有环」，使软件调度器常常无事可做。CPU 亲和与 IRQ 亲和决定尾延迟。不要把本课写成闪存磨损均衡：那是盘内 FTL，OS 看见的是命名空间。",-1)),(r(),t(d,null,{default:a(()=>[o(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20OLD%5B%22SCSI%20%E6%97%B6%E4%BB%A3%22%5D%0A%20%20%20%20A1%5B%22%E6%89%80%E6%9C%89%20CPU%20%E6%8F%90%E4%BA%A4%22%5D%20--%3E%20A2%5B%22%E5%85%A8%E5%B1%80%E8%AF%B7%E6%B1%82%E9%94%81%22%5D%0A%20%20%20%20A2%20--%3E%20A3%5B%22%E4%B8%80%E6%9D%A1%E6%B7%B1%E9%98%9F%E5%88%97%22%5D%0A%20%20end%0A%20%20subgraph%20NEW%5B%22NVMe%20%E6%AF%8F%E6%A0%B8%E9%98%9F%E5%88%97%E5%AF%B9%22%5D%0A%20%20%20%20B1%5B%22CPU%200%22%5D%20--%3E%20B2%5B%22SQ0%20%E4%B8%8E%20CQ0%22%5D%0A%20%20%20%20B3%5B%22CPU%201%22%5D%20--%3E%20B4%5B%22SQ1%20%E4%B8%8E%20CQ1%22%5D%0A%20%20%20%20B5%5B%22CPU%20n%22%5D%20--%3E%20B6%5B%22SQn%20%E4%B8%8E%20CQn%22%5D%0A%20%20end%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[s(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=i('<p><span class="marginnote">直觉类比：门铃寄存器就像餐厅叫号屏——你把订单（命令）逐份放进后厨传送带（SQ），然后更新叫号屏（写门铃），后厨看到号码就知道处理到哪一份，不用你逐份喊话。</span></p><p>与 <a href="/cs/sendfile-splice">sendfile</a>：页的 DMA 映射在这条路径上真正离开主机。</p><p>实现上：管理队列与 I/O 队列分开，重置命名空间走 admin。超时则驱动可 reset 整卡，影响该卡上所有命名空间。轮询队列要用户或 blk-mq 显式启用，不是默认 IRQ 路径。 读法上只引用<a href="/cs/blk-schedulers">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「存储栈 / 块层到设备」课序里，对象是 <strong>NVMe 队列与驱动</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 ZNS 区重置的全部命令集。不保证每家厂商的私有 log page。下一课看仍主宰机械盘、磁带与部分 SSD 的旧栈：SCSI。</p><p>版本字段会变，课序钉的是机制对象「NVMe 队列与驱动」，不是某一主线内核的结构体名。 后课默认：NVMe 用成对队列提交命令。SCSI 中层与 LUN 如何接到同一块层，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NVMe 每核 SQ/CQ 加门铃；完成走 CQ。</li><li>命名空间呈现为块设备。</li><li>SCSI 栈是下一课。</li><li>出处：NVMe Base Specification；Linux nvme；<em>OSTEP</em> 对 SSD 接口的背景。</li></ul>',10))])}const f=E(B,[["render",m]]);export{_ as __pageData,f as default};
